import { Board, CellCoord, Tile, cellKey, edgeNeighbors, emptyBoard, placeTile } from '@triominos/shared';

export interface PuzzlePoint {
  cell: CellCoord;
  values: [number, number, number];
}

export interface PuzzleLevel {
  id: string;
  name: string;
  /** The two fixed anchor tiles the player must connect. */
  pointA: PuzzlePoint;
  pointB: PuzzlePoint;
  /** The exact tiles handed to the player -- enough to connect the points, no spares. */
  tiles: Tile[];
}

/**
 * Each level was generated by literally playing a random legal chain out with the real
 * board engine (findLegalPlacements/placeTile), then taking its two ends as the points and
 * everything in between as the hand -- so a solution using every given tile is always
 * guaranteed to exist, and rejected if the two points already touched before any tile was
 * placed (which would make the puzzle trivial).
 */
